import requests
import json

token = "cccb2644-efc9-4a8b-b1dc-1a199df532d4"
domain = "m3brealty.haus"

# Railway GraphQL API
url = "https://api.railway.app/graphql"

query = """
query {
  projects(first: 100) {
    edges {
      node {
        id
        name
      }
    }
  }
}
"""

headers = {
    "Authorization": f"Bearer {token}",
    "Content-Type": "application/json"
}

response = requests.post(url, json={"query": query}, headers=headers)
print(response.text)
EOF
python3 /tmp/add_domain.py 2>&1

